package houyidb

import "testing"

// StableID 四方对拍：期望值由 Python SDK（hashlib.blake2b(digest_size=8)）
// 生成，与 TS SDK、服务端网关同算法。跨语言一致是 delete 重放的前提。
// EN: StableID four-way cross-check: expected values are generated by the
// Python SDK (hashlib.blake2b(digest_size=8)) with the same algorithm as the
// TS SDK and the server gateway. Cross-language consistency is the
// precondition for delete replay.
func TestStableIDMatchesPython(t *testing.T) {
	cases := map[string]uint64{
		"":        7252660547403494068,
		"hello":   2861735919082615933,
		"node-42": 6694704320175634731,
		"苹果香蕉":    4490440666094115033,
		"doc-1":   6265767295393789249,
		"a/b?c#d": 4199517732852746375,
	}
	for text, want := range cases {
		if got := StableID(text); got != want {
			t.Errorf("StableID(%q) = %d, want %d", text, got, want)
		}
	}
}

func TestStableIDDeterministicPositiveHalf(t *testing.T) {
	a := StableID("same-input")
	if StableID("same-input") != a {
		t.Error("StableID must be deterministic")
	}
	if a > uint64(1)<<63-1 {
		t.Errorf("StableID must land in the positive u64 half, got %d", a)
	}
}
